head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = "ULDFIS00100_P3.gfm";

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    const arrPar = $p.getParentWindow().scwin.fn_GetParAffCoCd();
    ibx_entprGrpNm.setValue(arrPar[0]);
    if (ibx_entprGrpNm.getValue() !== "") {
        scwin.search();
    } else {
        ibx_entprGrpNm.focus();
    }
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.btn_close_onclick = function() {
    // 닫기버튼 클릭
    scwin.closeFrame();
};

scwin.btn_confirm_onclick = function() {
    // 확인버튼 클릭
    scwin.setParam();
};

scwin.ibx_entprGrpNm_onkeydown = function() {
    // 기업집단명 엔터
    if (event.keyCode === 13) {
        scwin.search();
    }
};

scwin.btn_search_onclick = function() {
    // 조회 버튼 클릭
    scwin.search();
};

scwin.grd_entprGrpList_oncelldblclick = function (rowIndex, columnIndex, columnId) {
	    // 그리드 더블클릭
    scwin.setParam(rowIndex);
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.sbm_entprGrpList_submitdone = function (e) {
    dlt_entprGrpListRes.setJSON(e.responseJSON.body);
    tbx_totCnt.setValue(dlt_entprGrpListRes.getRowCount());
    // 데이터셋 OnLoadCompleted
    // if (dlt_entprGrpListRes.errorMsg) {
    //     alert(dlt_entprGrpListRes.errorMsg);
    // } else {
    //     // tbx_totCnt.setValue("총 " + dlt_entprGrpListRes.getRowCount() + " 건");
    //     tbx_totCnt.setValue(dlt_entprGrpListRes.getTotalRow());
    // }
};

scwin.sbm_entprGrpList_submiterror = function (e) {
    $c.win.alert(dlt_entprGrpListRes);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_entprGrpListRes.removeAll();
    tbx_totCnt.setValue("");
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    //필수항목 체크.
    if (ibx_entprGrpNm.getValue() === "") {
        alert("기업집단명을 입력하세요.");
        ibx_entprGrpNm.focus();
        return false;
    }
    return true;
};

/**
 * 기업목록 조회
 */
scwin.search = function() {
    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    const reqMap = {
        entprGrpNm: ibx_entprGrpNm.getValue(), //기업집단명
    };
    $c.sbm.execute(sbm_entprGrpList, reqMap);
};

/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.setParam = function(v_Currow) {
    if (v_Currow === undefined) {
        v_Currow = dlt_entprGrpListRes.getRowPosition();
    }
    // var arrPar = new Array();
    // arrPar[0] = {
    //     entprGrpCd: dlt_entprGrpListRes.getCellData(v_Currow, "entprGrpCd"), //기업집단코드	
    //     entprGrpNm: dlt_entprGrpListRes.getCellData(v_Currow, "entprGrpNm") //기업집단명
    // };

	// //----W-Craft WebSquare 변환 확인: fn_SetParAffCoCd----//
    // opener.fn_SetParAffCoCd(arrPar);
    // scwin.fn_CloseFrame();

    const res = dlt_entprGrpListRes.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};

/**
 * close frame
 */
scwin.closeFrame = async function() {
    // await $c.frame.CloseFrame();
    $c.win.closePopup();
};
